const out = {};
const task = `Implement the CSV-AS-DATABASE portion of /Users/astahmer/dev/dadabase/plans/csv-database-and-duckdb.md (feature B). cwd = /Users/astahmer/dev/dadabase.

CONTEXT: Three prior attempts died at startup from provider 503 outages — no partial work exists. @ = tzszqvqtoonp contains the completed, gate-verified DuckDB driver. Start with \`jj new -m "feat: CSV files as editable databases"\` on top of it, then build feature B per plan decision §B.1 (in-memory DuckDB over read_csv_auto).

RESOURCE DISCIPLINE: batched rg/sed edits, no wholesale node_modules reads, progressively scoped vitest runs.

Follow the plan's Phase B checkboxes: connection kind + form UX (path picker; single file or directory of *.csv), table listing/naming from filenames, schema inference display, LIMIT/OFFSET paging, staged edits with explicit Save -> atomic write-back (+ .bak backup), unsaved-changes indicator, large-file guidance, colocated tests incl. round-trip (load -> edit cell -> save -> reload shows change + valid csv).
Gates: pnpm typecheck (keep 0 errors), pnpm lint (<= 8 pre-existing errors), scoped pnpm test --run. Report phases done + gate results + any plan deviations with reasoning.`;

let attempt = 0;
let lastError = '';
while (attempt < 3) {
  try {
    const r = await runs.run('csv-retry-' + attempt, { agent: 'worker', maxRuntimeMs: 120 * 60 * 1000, task });
    const text = String(r.output ?? '');
    if (text.trim().length === 0) { lastError = 'empty output'; attempt += 1; continue; }
    out.csv = text.slice(-900);
    return { status: 'complete', attempts: attempt + 1, ...out };
  } catch (e) {
    lastError = String(e);
    attempt += 1;
  }
}
return { abortedAt: 'csv-database', attempts: attempt, error: lastError };
